46	export default function transformProps(
47	  chartProps: BigNumberWithTrendlineChartProps,
48	): BigNumberVizProps {
49	  const {
50	    width,
51	    height,
52	    queriesData,
53	    formData,
54	    rawFormData,
55	    theme,
56	    hooks,
57	    inContextMenu,
58	    datasource: { currencyFormats = {}, columnFormats = {} },
59	  } = chartProps;
60	  const {
61	    colorPicker,
62	    compareLag: compareLag_,
63	    compareSuffix = '',
64	    timeFormat,
65	    metricNameFontSize,
66	    headerFontSize,
67	    metric = 'value',
68	    showTimestamp,
69	    showTrendLine,
70	    subtitle = '',
71	    subtitleFontSize,
72	    aggregation,
73	    startYAxisAtZero,
74	    subheader = '',
75	    subheaderFontSize,
76	    forceTimestampFormatting,
77	    yAxisFormat,
78	    currencyFormat,
79	    timeRangeFixed,
80	  } = formData;
81	  const granularity = extractTimegrain(rawFormData);
82	  const {
83	    data = [],
84	    colnames = [],
85	    coltypes = [],
86	    from_dttm: fromDatetime,
87	    to_dttm: toDatetime,
88	  } = queriesData[0];
89	
90	  const aggregatedQueryData = queriesData.length > 1 ? queriesData[1] : null;
91	
92	  const hasAggregatedData =
93	    aggregatedQueryData?.data &&
94	    aggregatedQueryData.data.length > 0 &&
95	    aggregation !== 'LAST_VALUE';
96	
97	  const aggregatedData = hasAggregatedData ? aggregatedQueryData.data[0] : null;
98	  const refs: Refs = {};
99	  const metricName = getMetricLabel(metric);
100	  const metrics = chartProps.datasource?.metrics || [];
101	  const originalLabel = getOriginalLabel(metric, metrics);
102	  const showMetricName = chartProps.rawFormData?.show_metric_name ?? false;
103	  const compareLag = Number(compareLag_) || 0;
104	  let formattedSubheader = subheader;
105	
106	  const { r, g, b } = colorPicker;
107	  const mainColor = `rgb(${r}, ${g}, ${b})`;
108	
109	  const xAxisLabel = getXAxisLabel(rawFormData) as string;
110	  let trendLineData: TimeSeriesDatum[] | undefined;
111	  let percentChange = 0;
112	  let bigNumber = data.length === 0 ? null : data[0][metricName];
113	  let timestamp = data.length === 0 ? null : data[0][xAxisLabel];
114	  let bigNumberFallback = null;
115	  let sortedData: [number | null, number | null][] = [];
116	
117	  if (data.length > 0) {
118	    sortedData = (data as BigNumberDatum[])
119	      .map(
120	        d =>
121	          [d[xAxisLabel], parseMetricValue(d[metricName])] as [
122	            number | null,
123	            number | null,
124	          ],
125	      )
126	      // sort in time descending order
127	      .sort((a, b) => (a[0] !== null && b[0] !== null ? b[0] - a[0] : 0));
128	  }
129	  if (hasAggregatedData && aggregatedData) {
130	    if (
131	      aggregatedData[metricName] !== null &&
132	      aggregatedData[metricName] !== undefined
133	    ) {
134	      bigNumber = aggregatedData[metricName];
135	    } else {
136	      const metricKeys = Object.keys(aggregatedData).filter(
137	        key =>
138	          key !== xAxisLabel &&
139	          aggregatedData[key] !== null &&
140	          typeof aggregatedData[key] === 'number',
141	      );
142	      bigNumber = metricKeys.length > 0 ? aggregatedData[metricKeys[0]] : null;
143	    }
144	
145	    timestamp = sortedData.length > 0 ? sortedData[0][0] : null;
146	  } else if (sortedData.length > 0) {
147	    bigNumber = sortedData[0][1];
148	    timestamp = sortedData[0][0];
149	
150	    if (bigNumber === null) {
151	      bigNumberFallback = sortedData.find(d => d[1] !== null);
152	      bigNumber = bigNumberFallback ? bigNumberFallback[1] : null;
153	      timestamp = bigNumberFallback ? bigNumberFallback[0] : null;
154	    }
155	  }
156	
157	  if (compareLag > 0 && sortedData.length > 0) {
158	    const compareIndex = compareLag;
159	    if (compareIndex < sortedData.length) {
160	      const compareFromValue = sortedData[compareIndex][1];
161	      const compareToValue = sortedData[0][1];
162	      // compare values must both be non-nulls
163	      if (compareToValue !== null && compareFromValue !== null) {
164	        percentChange = compareFromValue
165	          ? (Number(compareToValue) - compareFromValue) /
166	            Math.abs(compareFromValue)
167	          : 0;
168	        formattedSubheader = `${formatPercentChange(
169	          percentChange,
170	        )} ${compareSuffix}`;
171	      }
172	    }
173	  }
174	
175	  if (data.length > 0) {
176	    const reversedData = [...sortedData].reverse();
177	    // @ts-ignore
178	    trendLineData = showTrendLine ? reversedData : undefined;
179	  }
180	
181	  let className = '';
182	  if (percentChange > 0) {
183	    className = 'positive';
184	  } else if (percentChange < 0) {
185	    className = 'negative';
186	  }
187	
188	  const metricColtypeIndex = colnames.findIndex(name => name === metricName);
189	  const metricColtype =
190	    metricColtypeIndex > -1 ? coltypes[metricColtypeIndex] : null;
191	
192	  let metricEntry: Metric | undefined;
193	  if (chartProps.datasource?.metrics) {
194	    metricEntry = chartProps.datasource.metrics.find(
195	      metricEntry => metricEntry.metric_name === metric,
196	    );
197	  }
198	
199	  const formatTime = getDateFormatter(
200	    timeFormat,
201	    granularity,
202	    metricEntry?.d3format,
203	  );
204	
205	  const numberFormatter = getValueFormatter(
206	    metric,
207	    currencyFormats,
208	    columnFormats,
209	    metricEntry?.d3format || yAxisFormat,
210	    currencyFormat,
211	  );
212	
213	  const headerFormatter =
214	    metricColtype === GenericDataType.Temporal ||
215	    metricColtype === GenericDataType.String ||
216	    forceTimestampFormatting
217	      ? formatTime
218	      : numberFormatter;
219	
220	  if (trendLineData && timeRangeFixed && fromDatetime) {
221	    const toDatetimeOrToday = toDatetime ?? Date.now();
222	    if (!trendLineData[0][0] || trendLineData[0][0] > fromDatetime) {
223	      trendLineData.unshift([fromDatetime, null]);
224	    }
225	    if (
226	      !trendLineData[trendLineData.length - 1][0] ||
227	      trendLineData[trendLineData.length - 1][0]! < toDatetimeOrToday
228	    ) {
229	      trendLineData.push([toDatetimeOrToday, null]);
230	    }
231	  }
232	
