19	import {
20	  FC,
21	  KeyboardEvent,
22	  MouseEvent,
23	  useCallback,
24	  useEffect,
25	  useState,
26	} from 'react';
27	import { useSelector } from 'react-redux';
28	import rison from 'rison';
29	import { styled, SupersetClient, t } from '@superset-ui/core';
30	import { Icons, Switch, Button, Skeleton } from '@superset-ui/core/components';
31	import { CopyToClipboard } from 'src/components';
32	import { RootState } from 'src/dashboard/types';
33	import { CopyButton } from 'src/explore/components/DataTableControl';
34	import { findPermission } from 'src/utils/findPermission';
35	import CodeSyntaxHighlighter, {
36	  SupportedLanguage,
37	  preloadLanguages,
38	} from '@superset-ui/core/components/CodeSyntaxHighlighter';
39	import { useHistory } from 'react-router-dom';
40	
41	const CopyButtonViewQuery = styled(CopyButton)`
42	  ${({ theme }) => `
43			&& {
44				margin: 0 0 ${theme.sizeUnit}px;
45			}
46	  `}
47	`;
48	
49	export interface ViewQueryProps {
50	  sql: string;
51	  datasource: string;
52	  language?: SupportedLanguage;
53	}
54	
55	const StyledSyntaxContainer = styled.div`
56	  height: 100%;
57	  display: flex;
58	  flex-direction: column;
59	`;
60	
61	const StyledHeaderMenuContainer = styled.div`
62	  display: flex;
63	  flex-direction: row;
64	  justify-content: space-between;
65	  margin-top: ${({ theme }) => -theme.sizeUnit * 4}px;
66	  align-items: flex-end;
67	`;
68	
69	const StyledHeaderActionContainer = styled.div`
70	  display: flex;
71	  flex-direction: row;
72	  column-gap: ${({ theme }) => theme.sizeUnit * 2}px;
73	`;
74	
75	const StyledThemedSyntaxHighlighter = styled(CodeSyntaxHighlighter)`
76	  flex: 1;
77	`;
78	
79	const StyledLabel = styled.label`
80	  font-size: ${({ theme }) => theme.fontSize}px;
81	`;
82	
83	const DATASET_BACKEND_QUERY = {
84	  keys: ['none'],
85	  columns: ['database.backend'],
86	};
87	
88	const ViewQuery: FC<ViewQueryProps> = props => {
89	  const { sql, language = 'sql', datasource } = props;
90	  const datasetId = datasource.split('__')[0];
91	  const [formattedSQL, setFormattedSQL] = useState<string>();
92	  const [showFormatSQL, setShowFormatSQL] = useState(true);
93	  const history = useHistory();
94	  const currentSQL = (showFormatSQL ? formattedSQL : sql) ?? sql;
95	  const canAccessSQLLab = useSelector((state: RootState) =>
96	    findPermission('menu_access', 'SQL Lab', state.user?.roles),
97	  );
98	
99	  // Preload the language when component mounts to ensure smooth experience
100	  useEffect(() => {
101	    preloadLanguages([language]);
102	  }, [language]);
103	
104	  const formatCurrentQuery = useCallback(() => {
105	    if (formattedSQL) {
106	      setShowFormatSQL(val => !val);
107	    } else {
108	      const queryParams = rison.encode(DATASET_BACKEND_QUERY);
109	      SupersetClient.get({
110	        endpoint: `/api/v1/dataset/${datasetId}?q=${queryParams}`,
111	      })
112	        .then(({ json }) =>
113	          SupersetClient.post({
114	            endpoint: `/api/v1/sqllab/format_sql/`,
115	            body: JSON.stringify({
116	              sql,
117	              engine: json.result.database.backend,
118	            }),
119	            headers: { 'Content-Type': 'application/json' },
120	          }),
121	        )
122	        .then(({ json }) => {
123	          setFormattedSQL(json.result);
124	          setShowFormatSQL(true);
125	        })
126	        .catch(() => {
127	          setShowFormatSQL(true);
128	        });
129	    }
130	  }, [sql, datasetId, formattedSQL]);
131	
132	  const navToSQLLab = useCallback(
133	    (domEvent: KeyboardEvent<HTMLElement> | MouseEvent<HTMLElement>) => {
134	      const requestedQuery = {
135	        datasourceKey: datasource,
136	        sql: currentSQL,
137	      };
138	      if (domEvent.metaKey || domEvent.ctrlKey) {
139	        domEvent.preventDefault();
140	        window.open(
141	          `/sqllab?datasourceKey=${datasource}&sql=${currentSQL}`,
142	          '_blank',
143	        );
144	      } else {
145	        history.push('/sqllab', { state: { requestedQuery } });
146	      }
147	    },
148	    [history, datasource, currentSQL],
149	  );
150	
151	  useEffect(() => {
152	    formatCurrentQuery();
153	  }, [sql]);
154	
155	  return (
156	    <StyledSyntaxContainer key={sql}>
157	      <StyledHeaderMenuContainer>
158	        <StyledHeaderActionContainer>
159	          <CopyToClipboard
160	            text={currentSQL}
161	            shouldShowText={false}
162	            copyNode={
163	              <CopyButtonViewQuery
164	                buttonSize="small"
165	                icon={<Icons.CopyOutlined />}
166	              >
167	                {t('Copy')}
168	              </CopyButtonViewQuery>
169	            }
170	          />
171	          {canAccessSQLLab && (
172	            <Button onClick={navToSQLLab}>{t('View in SQL Lab')}</Button>
173	          )}
174	        </StyledHeaderActionContainer>
175	        <StyledHeaderActionContainer>
176	          <Switch
177	            id="formatSwitch"
178	            checked={!showFormatSQL}
179	            onChange={formatCurrentQuery}
180	          />
181	          <StyledLabel htmlFor="formatSwitch">
182	            {t('Show original SQL')}
183	          </StyledLabel>
184	        </StyledHeaderActionContainer>
185	      </StyledHeaderMenuContainer>
186	      {!formattedSQL && <Skeleton active />}
187	      {formattedSQL && (
188	        <StyledThemedSyntaxHighlighter
189	          language={language}
190	          customStyle={{ flex: 1 }}
191	        >
192	          {currentSQL}
193	        </StyledThemedSyntaxHighlighter>
194	      )}
195	    </StyledSyntaxContainer>
196	  );
197	};
198	
199	export default ViewQuery;
